const msg = $input.first().json;

if (msg.messages?.[0]?.from_me === true)  return [];

const phone = msg.messages?.[0]?.from;
const msgObj = msg.messages?.[0];

if (!phone || !msgObj) throw new Error('NO_MESSAGE');

let text = '';
let messageType = msgObj.type;
let imageId = null;
let audioId = null;

if (msgObj.type === 'text') {
  text = msgObj.text?.body || '';
} else if (msgObj.type === 'audio' || msgObj.type === 'voice') {
  text = '[AUDIO recibido - pendiente transcripción]';
  audioId = msgObj.audio?.id || msgObj.voice?.id || null;
} else if (msgObj.type === 'image') {
  text = '[IMAGEN recibida - caption: ' + (msgObj.image?.caption || 'sin caption') + ']';
  imageId = msgObj.image?.id || null;
} else if (msgObj.type === 'document') {
  text = '[DOCUMENTO recibido: ' + (msgObj.document?.fileName || 'sin nombre') + ']';
} else {
  text = '[Mensaje de tipo ' + msgObj.type + ']';
}

return [{ json: { phone, text, messageType, imageId, audioId } }];

const row = $json;

const botActive = row?.bot_active !== undefined ? row.bot_active : true;
const vendedor = row?.vendedor || null;
const etiqueta = row?.etiqueta || null;

return [{ json: { phone: row.phone, text: row.text, messageType: row.messageType, bot_active: botActive, vendedor, etiqueta } }];

